import { expect, test } from 'bun:test';
import { createHash } from 'node:crypto';
import { copyFile, mkdir, mkdtemp, rm, stat, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const prefix = 'packages/herdr-upstream/';
const directory = join(root, prefix);
// Generated by the unchanged native schema generator; the herdr-native CI job
// executes its generator-currentness test against the actual guarded crate.
const generatedSchema = 'docs/next/api/herdr-api.schema.json';

test('Herdr exclusions preserve upstream bytes and one native-generated schema', async () => {
  const { ignore } = await Bun.file(join(root, '.jscpd.json')).json() as { ignore: string[] };
  expect(ignore.filter(pattern => pattern === prefix + generatedSchema)).toHaveLength(1);
  const scopes = ignore.map(pattern => new Bun.Glob(pattern));
  const excluded = (path: string) => scopes.some(scope => scope.match(prefix + path));
  const original = await Bun.file(join(directory, 'SOURCE-MANIFEST.sha256')).text();
  expect(createHash('sha256').update(original).digest('hex')).toBe('c303652ea2d310b78fdc9222cb30b405915890c0522239c9daf734591cb08e8a');
  const manifest = new Map(original.trimEnd().split('\n').map(line => {
    const match = /^([0-9a-f]{64})  (.+)$/.exec(line);
    if (!match || match[2].startsWith('/') || match[2].split('/').includes('..')) throw new Error('Invalid Herdr source manifest');
    return [match[2], match[1]];
  }));
  expect(scopes.some(scope => scope.match('tests/herdr-source.test.ts'))).toBe(false);
  expect(scopes.some(scope => scope.match('packages/herdr-guard/source.rs'))).toBe(false);
  for await (const path of new Bun.Glob('**/*').scan({ cwd: join(root, 'packages/herdr-guard'), onlyFiles: true, dot: true })) {
    expect(scopes.some(scope => scope.match('packages/herdr-guard/' + path)), `Excluded owned guard file: ${path}`).toBe(false);
  }
  expect(excluded('PROVENANCE.md')).toBe(false);
  expect(excluded('SOURCE-MANIFEST.sha256')).toBe(false);
  const checked = new Set<string>();
  for await (const path of new Bun.Glob('**/*').scan({ cwd: directory, onlyFiles: true, dot: true })) {
    if (!excluded(path)) continue;
    expect(manifest.has(path), `Excluded non-upstream file: ${path}`).toBe(true);
    if (path === generatedSchema) {
      expect(await Bun.file(join(directory, path)).exists()).toBe(true);
      checked.add(path);
      continue;
    }
    const bytes = await Bun.file(join(directory, path)).arrayBuffer();
    expect(createHash('sha256').update(new Uint8Array(bytes)).digest('hex'), `Modified excluded upstream file: ${path}`).toBe(manifest.get(path));
    checked.add(path);
  }
  for (const path of manifest.keys()) if (excluded(path)) expect(checked.has(path), `Missing excluded upstream file: ${path}`).toBe(true);
  expect(checked.size).toBeGreaterThan(1000);
});

// Opted in by herdr-native after its checksum-verified Zig and archive provision.
// Execute the exact Actions admission body with real gzip/Zig, without network.
for (const [name, sourceManifest] of [
  ['uucode', 'build.zig.zon'], ['highway', 'pkg/highway/build.zig.zon'], ['pixels', 'pkg/wuffs/build.zig.zon'],
] as const) for (const variant of ['matching hash', 'wrong hash', 'truncated archive'] as const) {
  test.skipIf(process.env.LAZYSH_HERDR_ARCHIVE_FIXTURES !== '1')(`local ${name} admission: ${variant}`, async () => {
    const workflow = Bun.YAML.parse(await Bun.file(join(root, '.github/workflows/checks.yml')).text()) as {
      jobs: { 'herdr-native': { steps: { id?: string; run?: string; env?: Record<string, string> }[] } };
    };
    const admission = workflow.jobs['herdr-native'].steps.find(step => step.id === `${name}-admission`)!;
    expect(admission.run).toBeDefined();
    const expected = admission.env!.HERDR_PACKAGE_HASH;
    const manifest = await Bun.file(join(directory, 'vendor/libghostty-vt', sourceManifest)).text();
    expect(manifest).toContain(`.hash = "${expected}"`);
    const fixture = await mkdtemp(join(tmpdir(), `lazysh-${name}-admission-`));
    try {
      const archive = join(fixture, `${name}.tar.gz`);
      for (const path of ['build.zig', 'build.zig.zon']) {
        await copyFile(join(directory, 'vendor/libghostty-vt', path), join(fixture, path));
      }
      const original = Buffer.from(await Bun.file(join(process.env.HERDR_CI_ROOT!, `${name}.tar.gz`)).arrayBuffer());
      expect(original.length).toBeLessThanOrEqual(33554432);
      await writeFile(archive, variant === 'truncated archive' ? original.subarray(0, 32) : original);
      const child = Bun.spawn(['bash', '-e', '-c', admission.run!], { cwd: fixture,
        env: { ...process.env, HERDR_CI_ROOT: fixture, HERDR_ARCHIVE_NAME: name,
          HERDR_PACKAGE_HASH: variant === 'wrong hash' ? expected + '-wrong' : expected,
          ZIG_GLOBAL_CACHE_DIR: join(fixture, 'global'), ZIG_LOCAL_CACHE_DIR: join(fixture, 'local') },
        stdout: 'pipe', stderr: 'pipe' });
      const [exit, stdout, stderr] = await Promise.all([
        child.exited, new Response(child.stdout).text(), new Response(child.stderr).text(),
      ]);
      expect(exit).toBe(variant === 'matching hash' ? 0 : 1);
      expect(stdout).toBe('');
      if (variant === 'matching hash') expect(stderr).toBe('');
      else expect(stderr).toContain(variant === 'wrong hash' ? 'Herdr archive package hash mismatch' : 'unexpected end of file');
      const admitted = await stat(join(fixture, 'zig-pkg', expected)).then(value => value.isDirectory(), () => false);
      expect(admitted).toBe(variant !== 'truncated archive');
    } finally {
      await rm(fixture, { recursive: true, force: true });
    }
  }, 100_000);
}

test('CI seals guarded bytes before compiling independently admitted original stock source',async()=>{
  const workflow=Bun.YAML.parse(await Bun.file(join(root,'.github/workflows/checks.yml')).text()) as any;
  const producer=workflow.jobs['herdr-native'],steps=producer.steps;
  expect(producer['timeout-minutes']).toBe(30);
  expect(producer.outputs['stock-sha256']).toBe('${{ steps.stock-artifact.outputs.sha256 }}');
  const index=(id:string)=>steps.findIndex((step:any)=>step.id===id);
  const guardedUpload=steps.findIndex((step:any)=>step.with?.name==='guarded-herdr-${{ github.run_id }}-${{ github.run_attempt }}');
  expect(index('guarded-artifact')).toBeLessThan(guardedUpload);
  expect(guardedUpload).toBeLessThan(index('stock-source-download'));
  expect(index('stock-source')).toBeLessThan(index('stock-build'));
  expect(index('stock-build')).toBeLessThan(index('stock-artifact'));
  const download=steps[index('stock-source-download')];
  expect(download.env.HERDR_ARCHIVE_URL).toBe('https://codeload.github.com/herdrdev/herdr/tar.gz/2ecf19a92fc3a7fff75b6ce3655ef04f4625ec01');
  expect(download.run).toContain('--max-time 180');expect(download.run).toContain('--max-filesize 33554432');
  const source=steps[index('stock-source')],build=steps[index('stock-build')];
  expect(source.run).toContain('cbd4354f1c44530d9f094c2797380208c50f19b4d6350b6e5206e220133c3168');
  for(const step of [source,build]){
    expect(step.run).toContain('c303652ea2d310b78fdc9222cb30b405915890c0522239c9daf734591cb08e8a');
    expect(step.run).toContain('sha256sum --check --quiet "$manifest"');
    expect(step.run).toContain('-eq 1843');
  }
  expect(build['working-directory']).toBe('${{ runner.temp }}/lazysh-herdr-native/stock-source');
  expect(build.run).toContain('cargo +1.96.1 build --locked --bin herdr');
  expect(build.env.CARGO_TARGET_DIR).toBe('${{ runner.temp }}/lazysh-herdr-native/stock-target');
  expect(build.env.ZIG_LOCAL_CACHE_DIR).toBe(build.env.CARGO_TARGET_DIR+'/zig-local');
  expect(build.env.ZIG_GLOBAL_CACHE_DIR).toBe(build.env.CARGO_TARGET_DIR+'/zig-global');
  expect(steps[index('stock-artifact')].env.CARGO_TARGET_DIR).toBe(build.env.CARGO_TARGET_DIR);
  expect(steps[index('guarded-artifact')].env.CARGO_TARGET_DIR).toBeUndefined();
  const upload=steps.find((step:any)=>step.with?.name==='stock-herdr-${{ github.run_id }}-${{ github.run_attempt }}');
  expect(upload.with['retention-days']).toBe(3);expect(upload.with['if-no-files-found']).toBe('error');
});
test('stock source admission rejects changed archive bytes before extraction or compilation',async()=>{
  const workflow=Bun.YAML.parse(await Bun.file(join(root,'.github/workflows/checks.yml')).text()) as any;
  const admission=workflow.jobs['herdr-native'].steps.find((step:any)=>step.id==='stock-source').run;
  const fixture=await mkdtemp(join(tmpdir(),'lazysh-stock-source-rejection-'));
  try {
    await writeFile(join(fixture,'stock-source.tar.gz'),'wrong owned source bytes');
    const child=Bun.spawn(['bash','-e','-c',admission],{env:{...process.env,HERDR_CI_ROOT:fixture,GITHUB_WORKSPACE:root},stdout:'pipe',stderr:'pipe'});
    expect(await child.exited).toBe(1);
    expect(await stat(join(fixture,'stock-source')).then(()=>true,()=>false)).toBe(false);
  } finally {await rm(fixture,{recursive:true,force:true});}
});

test('same-run stock admission rejects changed binary, source, checkout or unknown receipt fields without executing the binary',async()=>{
  const workflow=Bun.YAML.parse(await Bun.file(join(root,'.github/workflows/checks.yml')).text()) as any;
  const admission=workflow.jobs['native-android-herdr-navigation'].steps.find((step:any)=>step.name==='Verify same-run stock Herdr').run;
  const fixture=await mkdtemp(join(tmpdir(),'lazysh-stock-receipt-')),directory=join(fixture,'lazysh-stock-herdr');
  await mkdir(directory);
  const bytes=Buffer.from('owned validation bytes; never a native executable'),digest=createHash('sha256').update(bytes).digest('hex');
  const receipt={schemaVersion:1,sourceCommit:'2ecf19a92fc3a7fff75b6ce3655ef04f4625ec01',archiveSha256:'cbd4354f1c44530d9f094c2797380208c50f19b4d6350b6e5206e220133c3168',manifestSha256:'c303652ea2d310b78fdc9222cb30b405915890c0522239c9daf734591cb08e8a',sourceFiles:1843,binarySha256:digest,checkout:'a'.repeat(40)};
  const mutations:Record<string,Record<string,unknown>>={source:{sourceCommit:'0'.repeat(40)},archive:{archiveSha256:'0'.repeat(64)},manifest:{manifestSha256:'0'.repeat(64)},files:{sourceFiles:0},receiptBinary:{binarySha256:'0'.repeat(64)},checkout:{checkout:'b'.repeat(40)},extra:{private:'not admitted'}};
  try {
    for(const variant of ['matching','binary','source','archive','manifest','files','receiptBinary','checkout','extra'] as const){
      await writeFile(join(directory,'herdr'),variant==='binary'?'changed validation bytes':bytes,{mode:0o600});
      await writeFile(join(directory,'source.json'),JSON.stringify({...receipt,...(mutations[variant]??{})}));
      const child=Bun.spawn(['bash','-e','-c',admission],{cwd:fixture,env:{...process.env,RUNNER_TEMP:fixture,STOCK_HERDR_SHA256:digest,GITHUB_SHA:receipt.checkout,GITHUB_ENV:join(fixture,'env')},stdout:'pipe',stderr:'pipe'});
      expect(await child.exited,variant).toBe(variant==='matching'?0:1);
    }
  } finally {await rm(fixture,{recursive:true,force:true});}
});

test('stock Zig package admission copies only into an absent destination and cannot nest caches',async()=>{
  const workflow=Bun.YAML.parse(await Bun.file(join(root,'.github/workflows/checks.yml')).text()) as any;
  const run=workflow.jobs['herdr-native'].steps.find((step:any)=>step.id==='stock-source').run as string;
  const copy=/test ! -e vendor\/libghostty-vt\/zig-pkg[\s\S]*$/.exec(run)?.[0];
  expect(copy).toBeDefined();expect(copy).not.toContain('cargo');
  const fixture=await mkdtemp(join(tmpdir(),'lazysh-stock-zig-copy-')),stock=join(fixture,'stock-source');
  const source=join(fixture,'herdr-upstream/vendor/libghostty-vt/zig-pkg'),destination=join(stock,'vendor/libghostty-vt/zig-pkg');
  try {
    await mkdir(source,{recursive:true});await mkdir(join(stock,'vendor/libghostty-vt'),{recursive:true});
    await writeFile(join(source,'owned-package'),'verified generated dependency fixture');
    for(const mode of ['absent','existing','symlink'] as const){
      if(mode==='symlink'){await rm(destination,{recursive:true});await symlink('missing-package-target',destination);}
      const child=Bun.spawn(['bash','-e','-c',copy!],{cwd:stock,env:{...process.env,HERDR_CI_ROOT:fixture},stdout:'pipe',stderr:'pipe'});
      expect(await child.exited,mode).toBe(mode==='absent'?0:1);
      expect(await stat(join(destination,'zig-pkg')).then(()=>true,()=>false)).toBe(false);
    }
  } finally {await rm(fixture,{recursive:true,force:true});}
});

test('guarded and stock artifact retention select distinct target bytes and publish the matching hash',async()=>{
  const workflow=Bun.YAML.parse(await Bun.file(join(root,'.github/workflows/checks.yml')).text()) as any;
  const steps=workflow.jobs['herdr-native'].steps;
  const fixture=await mkdtemp(join(tmpdir(),'lazysh-herdr-target-binding-')),base=join(fixture,'lazysh-herdr-native');
  const guarded=Buffer.from('guarded unit fixture bytes'),stock=Buffer.from('stock unit fixture bytes');
  try {
    for(const [target,bytes] of [['target',guarded],['stock-target',stock]] as const){
      const directory=join(base,target,'debug');await mkdir(directory,{recursive:true});await writeFile(join(directory,'herdr'),bytes);
    }
    for(const [id,expected,foreign] of [['guarded-artifact',guarded,stock],['stock-artifact',stock,guarded]] as const){
      const step=steps.find((value:any)=>value.id===id),output=join(fixture,id+'.out');
      const target=step.env.CARGO_TARGET_DIR?.replace('${{ runner.temp }}',fixture)??join(base,'target');
      const child=Bun.spawn(['bash','-e','-c',step.run],{env:{...process.env,HERDR_CI_ROOT:base,HERDR_ARTIFACT_DIRECTORY:step.env.HERDR_ARTIFACT_DIRECTORY,CARGO_TARGET_DIR:target,GITHUB_OUTPUT:output},stdout:'pipe',stderr:'pipe'});
      expect(await child.exited).toBe(0);
      const bytes=Buffer.from(await Bun.file(join(base,step.env.HERDR_ARTIFACT_DIRECTORY,'herdr')).arrayBuffer());
      expect(bytes.equals(expected),id).toBe(true);expect(bytes.equals(foreign),id).toBe(false);
      expect(await Bun.file(output).text()).toBe('sha256='+createHash('sha256').update(expected).digest('hex')+'\n');
    }
  } finally {await rm(fixture,{recursive:true,force:true});}
});

test('every Herdr consumer downloads the producer artifact by immutable ID behind a fail-closed guard',async()=>{
  const workflow=Bun.YAML.parse(await Bun.file(join(root,'.github/workflows/checks.yml')).text()) as any;
  const producer=workflow.jobs['herdr-native'];
  const isDownload=(step:any)=>String(step.uses??'').startsWith('actions/download-artifact@');
  const consumers=Object.entries(workflow.jobs as Record<string,any>).filter(([name,job])=>name!=='herdr-native'&&
    ([job.needs].flat().includes('herdr-native')||job.steps?.some((step:any)=>isDownload(step)&&/herdr/.test(String(step.with?.name??'')))));
  expect(consumers.length).toBeGreaterThan(0);
  const guards=new Set<string>();
  for(const [name,job] of consumers){
    expect(job.permissions,name).toEqual({contents:'read',actions:'read'});
    const downloads=job.steps.map((step:any,index:number)=>[step,index] as const).filter(([step])=>isDownload(step));
    expect(downloads.length,name).toBeGreaterThan(0);
    for(const [download,index] of downloads){
      // An attempt-scoped name cannot match the producer's attempt-1 upload on a failed-only rerun.
      expect(download.with.name,name).toBeUndefined();
      const flavor=/^\$\{\{ needs\.herdr-native\.outputs\.(guarded|stock)-id \}\}$/.exec(download.with['artifact-ids'])?.[1];
      expect(flavor,name).toBeDefined();
      expect(download.with['github-token'],name).toBe('${{ github.token }}');
      expect(download.with['merge-multiple'],name).toBe(true);
      const upload=producer.steps.find((step:any)=>`\${{ steps.${step.id}.outputs.artifact-id }}`===producer.outputs[`${flavor}-id`]);
      expect(upload?.uses,name).toStartWith('actions/upload-artifact@');
      expect(upload.with['if-no-files-found']).toBe('error');
      const guard=job.steps.slice(0,index).findLast((step:any)=>step.env?.HERDR_ARTIFACT_ID!==undefined);
      expect(guard?.env.HERDR_ARTIFACT_ID,name).toBe(download.with['artifact-ids']);
      expect(guard.if,name).toBe(download.if);
      guards.add(guard.run);
    }
  }
  for(const run of guards){
    for(const [id,valid] of [['13315783100',true],['7',true],['',false],['0',false],['012',false],['abc',false],['1 2',false],['13315783100,2',false],['1\n2',false]] as const){
      const child=Bun.spawn(['bash','-e','-c',run],{env:{...process.env,HERDR_ARTIFACT_ID:id},stdout:'pipe',stderr:'ignore'});
      expect(await child.exited,JSON.stringify(id)).toBe(valid?0:1);
      if(!valid)expect(await new Response(child.stdout).text()).toContain('::error::herdr-native did not publish a single artifact ID');
    }
  }
});
